INSERT INTO `story_description` VALUES (361, 'ipicciridi', 'IanniSpeakerDescription', 'con il racconto di <font color=\'#e75c06\'>Pif</font>', 'con il racconto di <font color=\'#e75c06\'>Pif</font>');
INSERT INTO `story_description` VALUES (362, 'ipicciridi', 'ImpastatoDescription', 'Peppino Impastato nasce da una famiglia di origine mafiosa. Il padre Luigi, pur non avendo un ruolo di primissimo piano, è molto legato al cognato Cesare Manzella, capomafia del paese, che cade nel 1963 nel primo attentato mafioso con un’autobomba.<br/><br/>Le scelte di Peppino sono, sin dall’inizio, in aperto contrasto con il contesto di nascita, tanto da essere cacciato da casa dal padre. Nel 1965 fonda il giornalino \"L’Idea socialista\" e aderisce al PSIUP (ala del partito socialista ostile all’alleanza con la democrazia cristiana).<br/><br/>Nel 1976 fonda <em>Radio Aut</em>, radio libera autofinanziata, con cui denuncia i delitti e gli affari dei mafiosi di Cinisi e Terrasini. Il programma più seguito è \"onda pazza\", trasmissione satirica con cui sbeffeggia mafiosi e politici. Conia il termine \"Mafiopoli\" fa nomi e cognomi di politici e mette alla berlina il capomafia Gaetano Badalamenti (spesso chiamato «Tano Seduto»).<br/><br/> Nel 1978 si candida nella lista di Democrazia Proletaria alle elezioni comunali, ma viene assassinato nella notte tra l\'8 e il 9 maggio del 1978, nel corso della campagna elettorale. Una carica di tritolo viene posta sotto il suo corpo, adagiato sui binari della ferrovia: si ipotizza il suicidio o che sia morto mente preparava un attentato.<br/><br/>Grazie all’impegno della madre Felicia Bartolotta (morta il 7 dicembre 2004), del fratello Giovanni, di diversi compagni di militanza politica e del “Centro Siciliano di documentazione” (aperto nel 1977 ed intitolato a Peppino), vent’anni dopo la sua morte vengono riaperte le indagini che dimostreranno che Peppino è stato rapito e ucciso prima di essere adagiato sui binari, con un ordigno sotto l’addome.<br/><br/>Per il suo omicidio nel 2001 il boss Vito Palazzolo viene condannato a trent’anni di carcere e, nel 2002, Gaetano Badalamenti alla pena dell’ergastolo.', 'Peppino Impastato nasce da una famiglia di origine mafiosa. Il padre Luigi, pur non avendo un ruolo di primissimo piano, è molto legato al cognato Cesare Manzella, capomafia del paese, che cade nel 1963 nel primo attentato mafioso con un’autobomba.<br/><br/>Le scelte di Peppino sono, sin dall’inizio, in aperto contrasto con il contesto di nascita, tanto da essere cacciato da casa dal padre. Nel 1965 fonda il giornalino \"L’Idea socialista\" e aderisce al PSIUP (ala del partito socialista ostile all’alleanza con la democrazia cristiana).<br/><br/>Nel 1976 fonda <em>Radio Aut</em>, radio libera autofinanziata, con cui denuncia i delitti e gli affari dei mafiosi di Cinisi e Terrasini. Il programma più seguito è \"onda pazza\", trasmissione satirica con cui sbeffeggia mafiosi e politici. Conia il termine \"Mafiopoli\" fa nomi e cognomi di politici e mette alla berlina il capomafia Gaetano Badalamenti (spesso chiamato «Tano Seduto»).<br/><br/> Nel 1978 si candida nella lista di Democrazia Proletaria alle elezioni comunali, ma viene assassinato nella notte tra l\'8 e il 9 maggio del 1978, nel corso della campagna elettorale. Una carica di tritolo viene posta sotto il suo corpo, adagiato sui binari della ferrovia: si ipotizza il suicidio o che sia morto mente preparava un attentato.<br/><br/>Grazie all’impegno della madre Felicia Bartolotta (morta il 7 dicembre 2004), del fratello Giovanni, di diversi compagni di militanza politica e del “Centro Siciliano di documentazione” (aperto nel 1977 ed intitolato a Peppino), vent’anni dopo la sua morte vengono riaperte le indagini che dimostreranno che Peppino è stato rapito e ucciso prima di essere adagiato sui binari, con un ordigno sotto l’addome.<br/><br/>Per il suo omicidio nel 2001 il boss Vito Palazzolo viene condannato a trent’anni di carcere e, nel 2002, Gaetano Badalamenti alla pena dell’ergastolo.');
INSERT INTO `story_description` VALUES (363, 'ipicciridi', 'ImpastatoGeofenceAlert', 'Sei in prossimità di via 9 maggio 1978, qua vicino è avvenuto l’attentato a Giuseppe \"Peppino\" Impastato.', 'Sei in prossimità di via 9 maggio 1978, qua vicino è avvenuto l’attentato a Giuseppe \"Peppino\" Impastato.');
