INSERT INTO `story_description_copy1` VALUES (371, 'ipicciridi', 'LaTorreSpeakerDescription', 'con il racconto di <font color=\'#e75c06\'>Giuseppe Tornatore</font>', 'con il racconto di <font color=\'#e75c06\'>Giuseppe Tornatore</font>');
INSERT INTO `story_description_copy1` VALUES (372, 'ipicciridi', 'MattarellaDescription', 'Piersanti Mattarella nasce a Castellamare del Golfo il 24 maggio 1935. Era un politico democristiano vicino ad Aldo Moro che operò una svolta profonda nell’amministrazione regionale siciliana.<br/><br/>Da presidente della regione, Mattarella allargò la maggioranza coinvolgendo il partito comunista nell’area di governo, per condurre in porto il suo piano di riforme incentrato sulla trasparenza e l’eliminazione degli sprechi e dei favoritismi nella pubblica amministrazione.<br/><br/>L’impegno per la legalità e per lo sviluppo del Meridione ispirò tutta la sua attività amministrativa e politica.<br/><br/>Muore il giorno dell\'Epifania del 1980, ucciso da un killer mentre si trovava dentro la sua auto, davanti alla sua famiglia. Mentre stavano per andare a messa.<br/><br/>Tra i primi ad arrivare sul luogo dell’omicidio, il fratello Sergio, l’attuale presidente della Repubblica, che provò a soccorrerlo. Piersanti morì tra le sue braccia.', 'Piersanti Mattarella nasce a Castellamare del Golfo il 24 maggio 1935. Era un politico democristiano vicino ad Aldo Moro che operò una svolta profonda nell’amministrazione regionale siciliana.<br/><br/>Da presidente della regione, Mattarella allargò la maggioranza coinvolgendo il partito comunista nell’area di governo, per condurre in porto il suo piano di riforme incentrato sulla trasparenza e l’eliminazione degli sprechi e dei favoritismi nella pubblica amministrazione.<br/><br/>L’impegno per la legalità e per lo sviluppo del Meridione ispirò tutta la sua attività amministrativa e politica.<br/><br/>Muore il giorno dell\'Epifania del 1980, ucciso da un killer mentre si trovava dentro la sua auto, davanti alla sua famiglia. Mentre stavano per andare a messa.<br/><br/>Tra i primi ad arrivare sul luogo dell’omicidio, il fratello Sergio, l’attuale presidente della Repubblica, che provò a soccorrerlo. Piersanti morì tra le sue braccia.');
INSERT INTO `story_description_copy1` VALUES (373, 'ipicciridi', 'MattarellaGeofenceAlert', 'Sei in prossimità di viale della Libertà, qua è avvenuto l’attentato all\'ex Presidente della regione Sicilia​Piersanti Mattarella.', 'Sei in prossimità di viale della Libertà, qua è avvenuto l’attentato all\'ex Presidente della regione Sicilia​Piersanti Mattarella.');
