INSERT INTO `story_description_copy1` VALUES (888, 'isop', 'AgostinoSpeakerDescription', 'con il racconto di <font color=\'#e75c06\'>Teresa Mannino</font>', 'con il racconto di <font color=\'#e75c06\'>Teresa Mannino</font>');
INSERT INTO `story_description_copy1` VALUES (889, 'isop', 'AparoDescription', 'Era un agente della Polizia di Stato, vice Brigadiere della Squadra Mobile di Palermo, in servizio prima alla sezione antirapina e poi alla \"Catturandi\". Per il suo coraggio e la dedizione al dovere meritò numerosi premi e riconoscimenti.<br/><br/>Il suo assassinio si deve quasi certamente alla vendetta delle cosche, o alla decisione di eliminare un \"segugio\" (come veniva chiamato) particolarmente efficiente e pericoloso o, probabilmente, per entrambi i motivi: il sottufficiale era infatti impegnato in delicate indagini per scoprire la struttura delle cosche mafiose palermitane.<br/><br/>Era il cervello fotografico della Squadra Mobile, il più ascoltato dai colleghi e funzionari, un archivio vivente della \"mala\".<br/><br/>Fu assassinato a 43 anni in un agguato in Piazzale Tenente Anelli, la mattina dell’11 gennaio 1979, poco dopo le 8:30 con numerosi colpi di una \"P 38\" e un fucile a canne mozze caricato a pallettoni di lupara, mentre salutava la moglie affacciata al balcone di casa.', 'Era un agente della Polizia di Stato, vice Brigadiere della Squadra Mobile di Palermo, in servizio prima alla sezione antirapina e poi alla \"Catturandi\". Per il suo coraggio e la dedizione al dovere meritò numerosi premi e riconoscimenti.<br/><br/>Il suo assassinio si deve quasi certamente alla vendetta delle cosche, o alla decisione di eliminare un \"segugio\" (come veniva chiamato) particolarmente efficiente e pericoloso o, probabilmente, per entrambi i motivi: il sottufficiale era infatti impegnato in delicate indagini per scoprire la struttura delle cosche mafiose palermitane.<br/><br/>Era il cervello fotografico della Squadra Mobile, il più ascoltato dai colleghi e funzionari, un archivio vivente della \"mala\".<br/><br/>Fu assassinato a 43 anni in un agguato in Piazzale Tenente Anelli, la mattina dell’11 gennaio 1979, poco dopo le 8:30 con numerosi colpi di una \"P 38\" e un fucile a canne mozze caricato a pallettoni di lupara, mentre salutava la moglie affacciata al balcone di casa.');
INSERT INTO `story_description_copy1` VALUES (890, 'isop', 'AparoGeofenceAlert', 'Sei in prossimità di piazzale Tenente Giuseppe Anelli, qua è avvenuto l’attentato al vice Brigadiere della Squadra mobile di Palermo Filadelfo Aparo.', 'Sei in prossimità di piazzale Tenente Giuseppe Anelli, qua è avvenuto l’attentato al vice Brigadiere della Squadra mobile di Palermo Filadelfo Aparo.');
