INSERT INTO `story_description_copy1` VALUES (951, 'isop', 'FranceseSpeakerDescription', 'con il racconto di <font color=\'#e75c06\'>Francesco Scianna</font>', 'con il racconto di <font color=\'#e75c06\'>Francesco Scianna</font>');
INSERT INTO `story_description_copy1` VALUES (952, 'isop', 'GiacconeDescription', 'Paolo Giaccone è stato uno dei più grandi esperti di medicina legale in Italia.<br/><br/>Era titolare della cattedra di medicina legale nella facoltà di Giurisprudenza e professore di ruolo di medicina legale nell’ateneo palermitano.<br/><br/>Aveva messo a punto una tecnica investigativa che sarebbe stata ripresa anche dall\' FBI. Fondatore della sezione di Palermo dell’AVIS.<br/><br/>Gli furono affidate le perizie e le autopsie di personaggi illustri uccisi dalla criminalità mafiosa, come il Presidente della Regione siciliana Piersanti Mattarella, il procuratore Gaetano Costa, il giudice Cesare Terranova, il giornalista Mario Francese.<br/><br/>Nel dicembre del 1981, a seguito di una sparatoria tra le vie di Bagheria tra alcuni mafiosi, Giaccone ebbe l\'incarico di esaminare un\'impronta digitale lasciata dal killer Giuseppe Marchese, nipote del boss Filippo Marchese della cosca di Corso dei Mille: era l\'unica prova che potesse incastrare gli assassini. Il medico ricevette delle pressioni perché aggiustasse le conclusioni della perizia dattiloscopica. Giaccone non si piegò alle ripetute minacce.<br/><br/>La mattina dell\'11 Agosto 1982, poco dopo le otto, mentre percorreva il viale alberato che conduce all\'ingresso dell\'ospedale Policlinico di Palermo, Giaccone venne raggiunto ed ucciso dai proiettili di due killer. Aveva 53 anni, lasciò una moglie e quattro figli.', 'Paolo Giaccone è stato uno dei più grandi esperti di medicina legale in Italia.<br/><br/>Era titolare della cattedra di medicina legale nella facoltà di Giurisprudenza e professore di ruolo di medicina legale nell’ateneo palermitano.<br/><br/>Aveva messo a punto una tecnica investigativa che sarebbe stata ripresa anche dall\' FBI. Fondatore della sezione di Palermo dell’AVIS.<br/><br/>Gli furono affidate le perizie e le autopsie di personaggi illustri uccisi dalla criminalità mafiosa, come il Presidente della Regione siciliana Piersanti Mattarella, il procuratore Gaetano Costa, il giudice Cesare Terranova, il giornalista Mario Francese.<br/><br/>Nel dicembre del 1981, a seguito di una sparatoria tra le vie di Bagheria tra alcuni mafiosi, Giaccone ebbe l\'incarico di esaminare un\'impronta digitale lasciata dal killer Giuseppe Marchese, nipote del boss Filippo Marchese della cosca di Corso dei Mille: era l\'unica prova che potesse incastrare gli assassini. Il medico ricevette delle pressioni perché aggiustasse le conclusioni della perizia dattiloscopica. Giaccone non si piegò alle ripetute minacce.<br/><br/>La mattina dell\'11 Agosto 1982, poco dopo le otto, mentre percorreva il viale alberato che conduce all\'ingresso dell\'ospedale Policlinico di Palermo, Giaccone venne raggiunto ed ucciso dai proiettili di due killer. Aveva 53 anni, lasciò una moglie e quattro figli.');
INSERT INTO `story_description_copy1` VALUES (953, 'isop', 'GiacconeGeofenceAlert', 'Sei in prossimità del Policlinico, qua è avvenuto l’attentato al dottor Paolo Giaccone.', 'Sei in prossimità del Policlinico, qua è avvenuto l’attentato al dottor Paolo Giaccone.');
