INSERT INTO `story_description_copy1` VALUES (956, 'isop', 'GiulianoGeofenceAlert', 'Sei in prossimità di via Francesco Paolo Di Blasi, qua è avvenuto l’attentato al vice questore Boris Giuliano.', 'Sei in prossimità di via Francesco Paolo Di Blasi, qua è avvenuto l’attentato al vice questore Boris Giuliano.');
