INSERT INTO `story_description_copy1` VALUES (958, 'isop', 'GiulianoSpeakerDescription', 'Giuseppe Costanza, Paolo Capuzzo,<br/><br/>Vincenzo Corbo, Gaspare Cervello', 'Giuseppe Costanza, Paolo Capuzzo,<br/><br/>Vincenzo Corbo, Gaspare Cervello');
INSERT INTO `story_description_copy1` VALUES (959, 'isop', 'GrassiDescription', 'Libero Grassi nasce a Catania nel 1924. A otto anni con la famiglia si trasferisce a Palermo. Antifascista, dopo essersi laureato in Giurisprudenza, rinuncia al sogno di una carriera da diplomatico per diventare imprenditore nel campo del tessile.<br/><br/>Così, con la moglie, Pina Maisano, inizia a gestire uno storico negozio di tessuti in centro a Palermo.<br/><br/>Libero e Pina hanno due figli, una barca e un’azienda fiorente.<br/><br/>Tutto sembra andare per il meglio, fino a quando l’attività, la storica fabbrica \"Sigma\", viene presa di mira da Cosa Nostra, che pretende il pagamento del pizzo.<br/><br/>Grassi, a differenza di altri imprenditori, ha il coraggio di opporsi alle richieste di racket della mafia e di uscire allo scoperto, denunciando gli estorsori e persino i suoi dipendenti lo aiutano, facendo scoprire alcuni degli emissari.<br/><br/>La condanna a morte di Grassi arriva dopo la pubblicazione sul Giornale di Sicilia di una lettera dove annuncia il suo rifiuto a cedere ai ricatti della mafia.<br/><br/>Lasciato solo in questa lotta dai suoi colleghi imprenditori e dalle istituzioni, è assassinato il 29 agosto 1991.<br/><br/>Due uomini armati di pistola calibro 38 gli sparano addosso quattro colpi, lasciandolo in una pozza di sangue. Anche quel maledetto giorno stava andando a lavorare, in una città dove voleva sentirsi e vivere come il suo nome: libero.', 'Libero Grassi nasce a Catania nel 1924. A otto anni con la famiglia si trasferisce a Palermo. Antifascista, dopo essersi laureato in Giurisprudenza, rinuncia al sogno di una carriera da diplomatico per diventare imprenditore nel campo del tessile.<br/><br/>Così, con la moglie, Pina Maisano, inizia a gestire uno storico negozio di tessuti in centro a Palermo.<br/><br/>Libero e Pina hanno due figli, una barca e un’azienda fiorente.<br/><br/>Tutto sembra andare per il meglio, fino a quando l’attività, la storica fabbrica \"Sigma\", viene presa di mira da Cosa Nostra, che pretende il pagamento del pizzo.<br/><br/>Grassi, a differenza di altri imprenditori, ha il coraggio di opporsi alle richieste di racket della mafia e di uscire allo scoperto, denunciando gli estorsori e persino i suoi dipendenti lo aiutano, facendo scoprire alcuni degli emissari.<br/><br/>La condanna a morte di Grassi arriva dopo la pubblicazione sul Giornale di Sicilia di una lettera dove annuncia il suo rifiuto a cedere ai ricatti della mafia.<br/><br/>Lasciato solo in questa lotta dai suoi colleghi imprenditori e dalle istituzioni, è assassinato il 29 agosto 1991.<br/><br/>Due uomini armati di pistola calibro 38 gli sparano addosso quattro colpi, lasciandolo in una pozza di sangue. Anche quel maledetto giorno stava andando a lavorare, in una città dove voleva sentirsi e vivere come il suo nome: libero.');
INSERT INTO `story_description_copy1` VALUES (960, 'isop', 'GrassiGeofenceAlert', 'Sei in prossimità di via Vittorio Alfieri, qua è avvenuto l’attentato all\'imprenditore Libero Grassi.', 'Sei in prossimità di via Vittorio Alfieri, qua è avvenuto l’attentato all\'imprenditore Libero Grassi.');
INSERT INTO `story_description_copy1` VALUES (961, 'isop', 'GrassiGeofenceTitle', 'Storia di Libero Grassi', 'Storia di Libero Grassi');
INSERT INTO `story_description_copy1` VALUES (962, 'isop', 'GrassiSpeakerDescription', 'con il racconto di <font color=\'#e75c06\'>Leo Gullotta</font>', 'con il racconto di <font color=\'#e75c06\'>Leo Gullotta</font>');
INSERT INTO `story_description_copy1` VALUES (963, 'isop', 'IanniDescription', 'Carmelo Iannì nasce a Palermo il 26 febbraio 1934.<br/><br/>Era un imprenditore alberghiero, sposato con tre figlie.<br/><br/>Nel 1977 prende in gestione un piccolo albergo sul lungomare di Carini, in provincia di Palermo, il “Riva Smeralda”.<br/><br/>La sua passione è avere cura dei turisti, accoglierli, coccolarli e farli sentire “a casa propria”.<br/><br/>La svolta della sua vita arriva nel 1980, quando la polizia gli chiede di fare infiltrare in hotel degli agenti, per smascherare alcuni malavitosi marsigliesi, in Sicilia per insegnare ai mafiosi palermitani come raffinare l’eroina. Carmelo dice subito “sì”.<br/><br/>Per quasi un mese i poliziotti intercettano conversazioni e telefonate utili per le loro indagini, fino al giorno del blitz in una villa di Trabia, vicino Palermo.<br/><br/>Tra gli arrestati c’è anche il  latitante Gerlando Alberti.<br/><br/>È proprio il boss dal carcere a ordinare l\'omicidio di Carmelo Iannì, responsabile ai suoi occhi di avere agevolato la polizia nelle indagini.<br/><br/>Quattro giorni dopo l\'arresto, un commando di due persone fa irruzione nella hall dell\'albergo e spara a Carmelo Iannì uccidendolo sul colpo, davanti alla moglie.<br/><br/>Era il 28 agosto 1980. Il giornalista Saverio Lodato ha definito Iannì \"la prima vittima civile di mafia\", Carlo Lucarelli \"un eroe normale\".', 'Carmelo Iannì nasce a Palermo il 26 febbraio 1934.<br/><br/>Era un imprenditore alberghiero, sposato con tre figlie.<br/><br/>Nel 1977 prende in gestione un piccolo albergo sul lungomare di Carini, in provincia di Palermo, il “Riva Smeralda”.<br/><br/>La sua passione è avere cura dei turisti, accoglierli, coccolarli e farli sentire “a casa propria”.<br/><br/>La svolta della sua vita arriva nel 1980, quando la polizia gli chiede di fare infiltrare in hotel degli agenti, per smascherare alcuni malavitosi marsigliesi, in Sicilia per insegnare ai mafiosi palermitani come raffinare l’eroina. Carmelo dice subito “sì”.<br/><br/>Per quasi un mese i poliziotti intercettano conversazioni e telefonate utili per le loro indagini, fino al giorno del blitz in una villa di Trabia, vicino Palermo.<br/><br/>Tra gli arrestati c’è anche il  latitante Gerlando Alberti.<br/><br/>È proprio il boss dal carcere a ordinare l\'omicidio di Carmelo Iannì, responsabile ai suoi occhi di avere agevolato la polizia nelle indagini.<br/><br/>Quattro giorni dopo l\'arresto, un commando di due persone fa irruzione nella hall dell\'albergo e spara a Carmelo Iannì uccidendolo sul colpo, davanti alla moglie.<br/><br/>Era il 28 agosto 1980. Il giornalista Saverio Lodato ha definito Iannì \"la prima vittima civile di mafia\", Carlo Lucarelli \"un eroe normale\".');
INSERT INTO `story_description_copy1` VALUES (964, 'isop', 'IanniGeofenceAlert', 'Sei in prossimità di Villagrazia di Carini, qua è avvenuto l’attentato all\'imprenditore Carmelo Iannì.', 'Sei in prossimità di Villagrazia di Carini, qua è avvenuto l’attentato all\'imprenditore Carmelo Iannì.');
