INSERT INTO `story_description_copy1` VALUES (1012, 'story_detail', 'content', 'Discover the first 22 \\\"stories\\\" and their narrators, update periodically this app to find out the new ones.', 'Scopri le prime 22 \\\"storie\\\" ed i loro narratori e aggiorna periodicamente l’app per conoscere le nuove.');
INSERT INTO `story_description_copy1` VALUES (1013, 'addiopizzo_detail', 'description', 'PIZZO-FREE', 'PIZZO-FREE');
INSERT INTO `story_description_copy1` VALUES (1014, 'addiopizzo_detail', 'content', 'This chapter tells Palermo from the entrepreneurs’ point of view, who say NO to protection money (pizzo), thanks to the support of antiracket comittees and associations like ADDIOPIZZO. It was born in 2004 in Palermo, Addiopizzo has marked, in fact, for the town an awakening from the long acquiescence in extortion rackets. For more info <a href=\'http://www.addiopizzo.org\'>www.addiopizzo.org</a>', 'NOma propone anche itinerari che condurranno alla scoperta delle realtà che aderiscono ad “Addiopizzo”, un movimento che agisce dal basso nato su iniziativa di un gruppo di giovani che hanno scelto di combattere la mafia promuovendo un sistema di economia virtuosa e libera dalla mafia attraverso lo strumento del “consumo critico”.<br/>La scelta di inserire all’interno di NOma tali itinerari nasce dalla volontà di rendere visibile uno dei tanti lasciti delle persone raccontate da NOma che, attraverso il proprio sacrificio, hanno, appunto, risvegliato le coscienze e reso possibile una piccola rivoluzione.<br/>Per info: <a href=\'http://www.addiopizzo.org\'>www.addiopizzo.org</a>');
INSERT INTO `story_description_copy1` VALUES (1015, 'isop_detail', 'description', 'chi c\'era e c\'è ancora', 'chi c\'era e c\'è ancora');
